CREATE TABLE [import_batches] (
    [id] bigint IDENTITY(1,1) NOT NULL,
    [entity] nvarchar(30) NOT NULL,
    [file_name] nvarchar(255) NOT NULL,
    [status] nvarchar(20) NOT NULL,
