    [incomplete_rows] int NOT NULL CONSTRAINT [df_import_batches_incomplete_rows] DEFAULT 0,
    [invalid_rows] int NOT NULL CONSTRAINT [df_import_batches_invalid_rows] DEFAULT 0,
    [imported_rows] int NOT NULL CONSTRAINT [df_import_batches_imported_rows] DEFAULT 0,
    [options] nvarchar(max),
