    [description] nvarchar(255) NOT NULL,
    [percentage] decimal(7,4),
    [amount] decimal(18,2) NOT NULL,
    [due_date] date,
    [deliverable] nvarchar(max),
    [responsibility_center] nvarchar(100),
    [mfo_pap] nvarchar(255),
    [uacs_code] nvarchar(50),
    [status] nvarchar(20) NOT NULL CONSTRAINT [df_payment_tranches_status] DEFAULT N'pending',
    [ors_number] nvarchar(50),
    [dv_number] nvarchar(50),
    [created_by] bigint,
    [approved_by] bigint,
    [approved_at] datetime2(0),
    [paid_by] bigint,
    [paid_at] datetime2(0),
    [paid_date] date,
    [payment_method] nvarchar(20),
    [payment_reference] nvarchar(100),
    [amount_paid] decimal(18,2),
    [retention_amount] decimal(18,2) NOT NULL CONSTRAINT [df_payment_tranches_retention_amount] DEFAULT 0,
    [ld_deducted] decimal(18,2) NOT NULL CONSTRAINT [df_payment_tranches_ld_deducted] DEFAULT 0,
    [withholding_tax] decimal(18,2) NOT NULL CONSTRAINT [df_payment_tranches_withholding_tax] DEFAULT 0,
    [remarks] nvarchar(max),
    [created_at] datetime2(0),
    [updated_at] datetime2(0),
    CONSTRAINT [payment_tranches_pkey] PRIMARY KEY ([id]),
    CONSTRAINT [payment_tranches_owner_check] CHECK ((((contract_id IS NOT NULL) AND (purchase_order_id IS NULL)) OR ((contract_id IS NULL) AND (purchase_order_id IS NOT NULL)))),
    CONSTRAINT [payment_tranches_status_check] CHECK (((status) IN (N'pending', N'for_payment', N'paid'))),
    CONSTRAINT [payment_tranches_method_check] CHECK (((payment_method IS NULL) OR ((payment_method) IN (N'check', N'ada', N'lddap_ada')))),
    CONSTRAINT [payment_tranches_amount_check] CHECK ((amount > (0)))
);
