    [fund_source] nvarchar(255),
    [procurement_mode] nvarchar(100),
    [procurement_category] nvarchar(100) NOT NULL CONSTRAINT [df_purchase_request_items_procurement_category] DEFAULT N'Goods',
    CONSTRAINT [purchase_request_items_pkey] PRIMARY KEY ([id])
);
CREATE TABLE [purchase_requests] (
    [id] bigint IDENTITY(1,1) NOT NULL,
    [pr_number] nvarchar(255) NOT NULL,
    [department_id] bigint NOT NULL,
    [requested_by] bigint NOT NULL,
    [request_date] date NOT NULL,
    [purpose] nvarchar(max),
    [status] nvarchar(30) NOT NULL CONSTRAINT [df_purchase_requests_status] DEFAULT N'draft',
    [priority] nvarchar(255) NOT NULL CONSTRAINT [df_purchase_requests_priority] DEFAULT N'medium',
    [total_amount] decimal(12,2),
    [remarks] nvarchar(max),
    [created_at] datetime2(0),
    [updated_at] datetime2(0),
    [deleted_at] datetime2(0),
    [current_step] int,
    [app_id] bigint,
    [fiscal_year] smallint,
    [return_reason] nvarchar(max),
    [cancelled_at] datetime2(0),
    [caf_number] nvarchar(255),
    [caf_certified_by] bigint,
    [caf_certified_at] datetime2(0),
    [caf_amount] decimal(15,2),
    [caf_remarks] nvarchar(max),
    CONSTRAINT [purchase_requests_pkey] PRIMARY KEY ([id]),
    CONSTRAINT [purchase_requests_priority_check] CHECK (((priority) IN (N'low', N'medium', N'high')))
);
CREATE TABLE [request_items] (
    [id] bigint IDENTITY(1,1) NOT NULL,
    [request_id] bigint NOT NULL,
    [item_id] bigint NOT NULL,
    [quantity] int NOT NULL,
    [approved_quantity] int NOT NULL CONSTRAINT [df_request_items_approved_quantity] DEFAULT 0,
    [status] nvarchar(255) NOT NULL CONSTRAINT [df_request_items_status] DEFAULT N'pending',
