CREATE TABLE [requests] (
    [id] bigint IDENTITY(1,1) NOT NULL,
    [request_number] nvarchar(255) NOT NULL,
    [department_id] bigint,
    [requested_by] bigint,
    [request_date] date,
    [status] nvarchar(255) NOT NULL CONSTRAINT [df_requests_status] DEFAULT N'pending',
    [priority] nvarchar(255) NOT NULL CONSTRAINT [df_requests_priority] DEFAULT N'medium',
    [purpose] nvarchar(max),
    [created_at] datetime2(0),
    [updated_at] datetime2(0),
    [ris_number] nvarchar(255),
    [ris_date] date,
    [requisitioner] nvarchar(255),
    [par_number] nvarchar(255),
    [par_date] date,
    [employee_name] nvarchar(255),
    [position] nvarchar(255),
    [property_number] nvarchar(255),
    [description] nvarchar(max),
    [ics_number] nvarchar(255),
    [ics_date] date,
    [custodian_name] nvarchar(255),
    [office_department] nvarchar(255),
    [item_description] nvarchar(255),
