    CONSTRAINT [requests_status_check] CHECK (((status) IN (N'pending', N'approved', N'rejected', N'partially_fulfilled', N'fulfilled'))),
    CONSTRAINT [requests_priority_check] CHECK (((priority) IN (N'low', N'medium', N'high')))
